int find(int arr[], int lo, int hi, int val, int dep) {
    if (dep == 0) {
        return lo;
    }
    int mid = (lo + hi) / 2;
    if (arr[mid] < val) {
        return find(arr, mid, hi, val, dep - 1);
    }
    return find(arr, lo, mid - 1, val, dep - 1);
}
int a[4] = {1, 4, 6, 9};
int result = find(a, 0, 3, 7, 3);

